'use strict';
/* lib/meeting-register.js — a meeting's action register, the meeting's first-class output (owner ruling 2026-11-18).
 *
 * Sections: owner rulings, actions (each: item, owner, date, status, a PLAIN-LANGUAGE line, affects), open questions,
 * kill conditions, and "Not recorded here". NOT generated by a model: a row comes from the line its owner wrote in the
 * meeting (ACTION: / QUESTION: / KILL:, the speaker owns it), from the owner's controls (rulings, not recorded), or from
 * meeting-register.js update by the row's own owner later. Each owner updates only their own lines; the owner (lib/owner.js)
 * owns the rulings. A row with no plain-language line (or an action with no owner, date or status) fails validation and
 * is shown as such, except a line a seat wrote at the meeting table: there the plain part is welcome, not required
 * (add(..., {plainOptional: true}) marks the row, and the writer is told on its next turn). An owner ruling goes to decisions.md once the owner confirms it (decision.js add, by the owner).
 *
 *   load(id) / save(reg)        company/state/meetings/register/<id>.json (0600), and the rendered markdown
 *                               company/work/meetings/<date>-<id>-register.md
 *   add(reg, section, row, by, {plainOptional}) -> row (numbered); refused if invalid
 *   update(reg, section, n, patch, by, isOwner) -> row; refused unless `by` owns the row (rulings: the owner)
 *   validate(section, row)      -> [errors]
 *   parseLine(kind, text)       ACTION: <item> — by <date> — plain: <line> — affects: <who> [— status: <s>]
 *   render(reg, names)          the markdown, in the shape of the owner's table registers
 */
const fs = require('fs');
const path = require('path');
const co = require('./company');

const SECTIONS = ['rulings', 'actions', 'questions', 'kills', 'notRecorded'];
const TITLES = { rulings: 'Owner rulings', actions: 'Actions', questions: 'Open questions', kills: 'Kill conditions', notRecorded: 'Not recorded here' };
const dir = () => co.p('company', 'state', 'meetings', 'register');
const file = id => path.join(dir(), String(id).replace(/[^a-z0-9-]/g, '') + '.json');
const readJ = f => { try { return JSON.parse(fs.readFileSync(f, 'utf8')); } catch (_) { return null; } };
const clean = (s, n) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, n || 600);

function blank(id, meta) {
  return { v: 1, id, date: (meta && meta.date) || co.localParts(new Date()).date, title: (meta && meta.title) || '', type: (meta && meta.type) || 'decision',
    summary: null, rulings: [], actions: [], questions: [], kills: [], notRecorded: [], updatedAt: null };
}
function load(id, meta) { const r = readJ(file(id)); if (r && r.id === id) { for (const s of SECTIONS) if (!Array.isArray(r[s])) r[s] = []; return r; } return blank(id, meta); }

function validate(section, row) {
  const errs = [];
  if (!SECTIONS.includes(section)) return ['no such section: ' + section];
  if (!clean(row.text)) errs.push('it says nothing');
  if (section !== 'notRecorded' && !clean(row.plain) && !row.plainOptional) errs.push('it has no plain-language line (plain: one sentence anyone can read)');
  if (section === 'actions') {
    if (!clean(row.owner)) errs.push('it has no owner');
    if (!clean(row.date)) errs.push('it has no date (a day, or "own loop")');
    if (!clean(row.status)) errs.push('it has no status');
  }
  return errs;
}
function add(reg, section, row, by, opts) {
  const r = { n: reg[section].reduce((m, x) => Math.max(m, x.n || 0), 0) + 1, text: clean(row.text), plain: clean(row.plain, 300), at: new Date().toISOString(), by: clean(by, 80) };
  if (opts && opts.plainOptional && !r.plain) r.plainOptional = true;
  if (section === 'actions') Object.assign(r, { owner: clean(row.owner || by, 80), date: clean(row.date, 60), status: clean(row.status || 'open', 300), affects: clean(row.affects, 200) });
  if (section === 'questions' || section === 'kills') r.owner = clean(row.owner || by, 80);
  if (section === 'rulings') Object.assign(r, { owner: 'owner', confirmed: !!row.confirmed, proposedBy: clean(row.proposedBy, 80) || null, decisionId: null });
  const errs = validate(section, r);
  if (errs.length) throw Object.assign(new Error('not recorded: ' + errs.join('; ')), { code: 'invalid', errors: errs });
  reg[section].push(r);
  return r;
}
function update(reg, section, n, patch, by, isOwner) {
  const row = (reg[section] || []).find(x => x.n === Number(n));
  if (!row) throw Object.assign(new Error('no row ' + section + ' ' + n), { code: 'missing' });
  const owns = section === 'rulings' || section === 'notRecorded' ? !!isOwner : String(row.owner || '').toLowerCase() === String(by || '').toLowerCase();
  if (!owns) throw Object.assign(new Error('only ' + (section === 'rulings' ? 'the owner' : row.owner) + ' updates this line (each owner updates their own)'), { code: 'not-yours' });
  const next = Object.assign({}, row);
  for (const k of ['status', 'plain', 'date', 'affects', 'text']) if (patch[k] != null) next[k] = clean(patch[k], k === 'plain' ? 300 : 600);
  if (patch.confirmed === true && section === 'rulings') next.confirmed = true;
  const errs = validate(section, next);
  if (errs.length) throw Object.assign(new Error('not updated: ' + errs.join('; ')), { code: 'invalid', errors: errs });
  next.updatedAt = new Date().toISOString(); next.updatedBy = clean(by, 80);
  Object.assign(row, next);
  return row;
}
// ACTION: <item> — by <date> — plain: <line> — affects: <who> — status: <s>   (segments in any order after the item)
function parseLine(kind, text) {
  const parts = String(text || '').split(/\s+[—–]\s+|\s+\|\s+|\s+-{2}\s+/).map(x => x.trim()).filter(Boolean);
  const out = { text: '', plain: '', date: '', affects: '', status: '' };
  const rest = [];
  for (const p of parts) {
    let m;
    if ((m = /^plain\s*:\s*(.+)$/i.exec(p))) out.plain = m[1];
    else if ((m = /^affects?\s*:\s*(.+)$/i.exec(p))) out.affects = m[1];
    else if ((m = /^status\s*:\s*(.+)$/i.exec(p))) out.status = m[1];
    else if ((m = /^(?:by|due|date\s*:)\s*(.+)$/i.exec(p))) out.date = m[1];
    else rest.push(p);
  }
  out.text = rest.join(' — ');
  if (kind === 'ACTION' && !out.status) out.status = 'open';
  return out;
}
function render(reg, names) {
  const nm = x => (names && names(x)) || (x === 'owner' ? ((co.config.owner && co.config.owner.name) || 'the owner') : co.nameOf(x)) || x;
  const L = ['# Meeting ' + reg.date + (reg.title ? ': ' + reg.title : '') + ': action register', '',
    '_Source: what was said at the meeting (' + reg.type + '), as recorded in the minutes, meeting-' + reg.date + '.md. Nothing here was written by a model on anyone\'s behalf: each line is its owner\'s, and each owner updates their own lines (node company/tools/meeting-register.js update)._', ''];
  if (reg.summary) L.push('**Closed with:** ' + reg.summary.text + (reg.summary.plain ? ' — in plain words: ' + reg.summary.plain : reg.summary.plainOptional ? '' : ' — (no plain-language line: fails validation)') + ' (' + nm(reg.summary.by) + ')', '');
  const bad = (s, r) => { const e = validate(s, r); return e.length ? ' **[fails validation: ' + e.join('; ') + ']**' : ''; };
  L.push('## ' + TITLES.rulings);
  if (!reg.rulings.length) L.push('_None._');
  reg.rulings.forEach(r => L.push(r.n + '. ' + r.text + ' — ' + (r.plain ? 'in plain words: ' + r.plain : '') + (r.confirmed ? ' (confirmed by the owner' + (r.decisionId ? ', decisions.md ' + r.decisionId : '') + ')' : ' (proposed' + (r.proposedBy ? ' by ' + nm(r.proposedBy) : '') + ', not yet confirmed by the owner)') + bad('rulings', r)));
  L.push('', '## ' + TITLES.actions, '| # | Item | In plain words | Owner | Date | Status | Affects |', '|---|---|---|---|---|---|---|');
  const cell = s => String(s || '').replace(/\|/g, '/');
  reg.actions.forEach(r => L.push('| ' + r.n + ' | ' + cell(r.text) + bad('actions', r) + ' | ' + cell(r.plain) + ' | ' + cell(nm(r.owner)) + ' | ' + cell(r.date) + ' | ' + cell(r.status) + ' | ' + cell(r.affects) + ' |'));
  for (const s of ['questions', 'kills']) {
    L.push('', '## ' + TITLES[s]);
    if (!reg[s].length) L.push('_None._');
    reg[s].forEach(r => L.push('- ' + r.text + (r.plain ? ' — in plain words: ' + r.plain : '') + (r.owner ? ' (' + nm(r.owner) + ')' : '') + bad(s, r)));
  }
  L.push('', '## ' + TITLES.notRecorded);
  if (!reg.notRecorded.length) L.push('_Nothing noted yet._');
  reg.notRecorded.forEach(r => L.push('- ' + r.text));
  return L.join('\n') + '\n';
}
function mdFile(reg) { return co.p('company', 'work', 'meetings', reg.date + '-' + reg.id + '-register.md'); }
function save(reg, names) {
  reg.updatedAt = new Date().toISOString();
  fs.mkdirSync(dir(), { recursive: true, mode: 0o700 }); try { fs.chmodSync(dir(), 0o700); } catch (_) {}
  const f = file(reg.id), t = f + '.' + process.pid + '.tmp'; fs.writeFileSync(t, JSON.stringify(reg, null, 1), { mode: 0o600 }); fs.renameSync(t, f);
  try { const m = mdFile(reg); fs.mkdirSync(path.dirname(m), { recursive: true }); fs.writeFileSync(m, render(reg, names)); } catch (_) {}
  return reg;
}
function problems(reg) {
  const out = [];
  for (const s of SECTIONS) for (const r of reg[s]) { const e = validate(s, r); if (e.length) out.push({ section: s, n: r.n, errors: e }); }
  if (reg.summary && !clean(reg.summary.plain) && !reg.summary.plainOptional) out.push({ section: 'summary', n: 0, errors: ['the END summary has no plain-language line'] });
  return out;
}
module.exports = { SECTIONS, TITLES, load, save, add, update, validate, parseLine, render, problems, mdFile, file };
